/**
 * The reactive half of the Kopffeld-Check gate — OBO-156.
 *
 * `resolveHeaderFieldCheckState` is pure and knows nothing about stores. This
 * is the piece that feeds it: preferences, the org's feature subscriptions,
 * and the shared Analytics verdict.
 *
 * ## Nothing about access is cached here
 *
 * The first build kept its own copies of the user's role ids and the org's
 * grants. Two ways that fails, both found in review:
 *
 * * `useAnalyticsAccess` clears the shared grants when an admin saves the
 *   roles page or the acting identity changes — a local copy does not hear
 *   about it, and the button stays alive for someone whose access was just
 *   revoked;
 * * a grant list that resolves BEFORE an invalidation can still be installed
 *   after it, because the shared loader's generation check cannot protect a
 *   result that had already resolved.
 *
 * So the verdict is read from `useAnalyticsAccess().accessGranted`, which is
 * a computed over the one cache that is invalidated properly. There is no
 * second copy to go stale.
 */

import { computed, type ComputedRef } from 'vue';
import { storeToRefs } from 'pinia';

import { useSettingStore } from 'src/store/Settings/setting.store';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import {
  FEATURE_ANALYTICS_DASHBOARD,
  analyticsAccessSettingsReady,
} from 'src/utils/analytics-access';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { subscriptionMatchesApp } from 'src/pages/Settings/Components/Subscription/subscriptionDialogHelpers';
import { CONSTANTS } from 'src/constants';
import {
  resolveHeaderFieldCheckState,
  type HeaderFieldCheckState,
} from 'src/utils/header-field-check-access';
import { useAnalyticsAccess } from 'src/composables/useAnalyticsAccess';
import { logger } from 'src/utils/logger';

export interface HeaderFieldCheckGate {
  /** Which of the three doors — or `ready`, or `loading`. */
  state: ComputedRef<HeaderFieldCheckState>;
  /** The button opens the report rather than a dialog. */
  canOpenReport: ComputedRef<boolean>;
  /** Loads everything the decision needs; resolves when it is decidable. */
  ensureLoaded: () => Promise<void>;
}

export function useHeaderFieldCheck(): HeaderFieldCheckGate {
  const settingStore = useSettingStore();
  const subscriptionStore = useSubscriptionStore();
  const { user_settings } = storeToRefs(settingStore);
  const { feature_subscriptions, feature_subscriptions_loaded } =
    storeToRefs(subscriptionStore);

  const analytics = useAnalyticsAccess();

  const state = computed<HeaderFieldCheckState>(() =>
    resolveHeaderFieldCheckState({
      settingsReady: analyticsAccessSettingsReady(user_settings.value),
      subscriptionsReady: feature_subscriptions_loaded.value === true,
      /**
       * `subscriptionMatchesApp`, not a plan-key prefix match. Its own
       * comment records why: a price-list realignment renamed plans, the
       * prefix map drifted, and an org's active subscription stopped being
       * recognised. A bundled plan (`ENTERPRISE_BUNDLE` carrying
       * `apps: [{app_key: 'DOC_SEARCH'}]`) is a real entitlement, and
       * greeting that customer with an upsell is the same incident again.
       */
      hasSubscription: (feature_subscriptions.value ?? []).some(
        (sub) =>
          sub?.is_active === true &&
          subscriptionMatchesApp(sub, CONSTANTS.analytics_dashboard),
      ),
      moduleEnabled: toBoolPreference(
        user_settings.value?.[FEATURE_ANALYTICS_DASHBOARD],
      ),
      analyticsGranted: analytics.accessGranted.value,
    }),
  );

  const canOpenReport = computed(() => state.value === 'ready');

  async function ensureLoaded(): Promise<void> {
    // Each half fails open on its own error and closed in effect: an unknown
    // module state, an unfetched grant list or an unreadable subscription list
    // all resolve to a door rather than to the report, which is already the
    // safe answer. Nothing here is worth failing the validation screen over.
    await Promise.all([
      analytics.ensureLoaded().catch(() => undefined),
      subscriptionStore.fetchFeatureSubscriptions().catch((error: unknown) => {
        logger.warn('[HEADER-FIELD-CHECK] subscription lookup failed', error);
        return undefined;
      }),
    ]);
  }

  return { state, canOpenReport, ensureLoaded };
}
